import React from 'react';
import './skills.css';
import { AiOutlineHtml5 } from 'react-icons/ai';
import { DiCss3, DiJavascript, DiReact, DiPhotoshop } from 'react-icons/di';
import { FiFigma } from 'react-icons/fi';

const SKILLS_DATA = [
  { id: 1, name: 'Html5', Icon: AiOutlineHtml5 },
  { id: 2, name: 'Javascript', Icon: DiJavascript },
  { id: 3, name: 'Css', Icon: DiCss3 },
  { id: 4, name: 'React', Icon: DiReact },
  { id: 5, name: 'Figma', Icon: FiFigma },
  { id: 6, name: 'Photoshop', Icon: DiPhotoshop },
];

const Skills = () => {
  return (
    <section id="skills">
      <h2>Mine ferdigheter</h2>

      <div className="container skills__container">
        <div className="skills">
          <ul className="ch-grid">
            {SKILLS_DATA.map(({ id, name, Icon }) => (
              <li key={id}>
                <div className="circle">
                  <div className="mask half">
                    <div className="fill"></div>
                  </div>
                  <div className="mask full">
                    <div className="fill"></div>
                  </div>
                  <div className="inside-circle"></div>
                  <Icon className="ch-img" />
                  <div className="ch-info">
                    {/* <h3>God kunnskap</h3> */}
                    <p>{name}</p>
                  </div>
                </div>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </section>
  );
};

export default Skills;