import React, { useState } from 'react';
import './projects.css';

import IMG01 from '../../assets/Pseudo_elements.png';
import IMG02 from '../../assets/Transitions.png';
import IMG03 from '../../assets/Calculator.png';
import IMG04 from '../../assets/Todo-list.png';
import IMG05 from '../../assets/drum_machine.jpg';
import IMG06 from '../../assets/prosjekt-phillips.png';
import ARTICLE_IMG from '../../assets/På vei mot jobb.jpg'; // Bytt ut med ønsket bilde for artikkelen

import { Navigation, Pagination, Keyboard, EffectCoverflow } from 'swiper/modules';
import { Swiper, SwiperSlide } from 'swiper/react';

import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import 'swiper/css/scrollbar';
import 'swiper/css/effect-coverflow';

const PROJECTS_DATA = [
    {
    id: 1,
    title: 'Innholdsproduksjon & tanker',
    image: ARTICLE_IMG,
    type: 'article',
  },
   {
    id: 2,
    title: 'Prosjekt Phillips',
    image: IMG06,
    link: 'https://www.phillipskarriere.no/',
    type: 'link',
  },
  {
    id: 3,
    title: 'Drum Machine',
    image: IMG05,
    link: 'https://github.com/monmath?tab=repositories',
    type: 'link',
  },
 {
    id: 4,
    title: 'Todo List',
    image: IMG04,
    link: 'https://github.com/monmath?tab=repositories',
    type: 'link',
  },
   {
    id: 5,
    title: 'Calculator',
    image: IMG03,
    link: 'https://github.com/monmath?tab=repositories',
    type: 'link',
  },
  {
    id: 6,
    title: 'Transitions',
    image: IMG02,
    link: 'https://github.com/monmath?tab=repositories',
    type: 'link',
  },
 
  {
    id: 7,
    title: 'Pseudo Elements',
    image: IMG01,
    link: 'https://github.com/monmath?tab=repositories',
    type: 'link',
  },
  
 
 
  
 
];

const Projects = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);

  return (
    <section id="projects">
      <h2>Mine Prosjekter</h2>

      <Swiper
        className="container projects__container"
        breakpoints={{
          0: { slidesPerView: 1 },
          768: { slidesPerView: 2 },
          1024: { slidesPerView: 3 },
        }}
        effect={'coverflow'}
        centeredSlides={true}
        slidesPerView={'auto'}
        spaceBetween={30}
        coverflowEffect={{
          rotate: 50,
          stretch: 0,
          depth: 100,
          modifier: 1,
          slideShadows: false,
        }}
        keyboard={{ enabled: true }}
        pagination={{ clickable: true }}
        navigation={{ clickable: true }}
        modules={[Keyboard, Pagination, Navigation, EffectCoverflow]}
      >
        {PROJECTS_DATA.map(({ id, title, image, link, type }) => (
          <SwiperSlide key={id}>
            <div className="projects-item">
              {type === 'article' ? (
                <div className="article-card" onClick={() => setIsModalOpen(true)}>
                  <div className="projects__item-image">
                    <img src={image} alt={title} />
                  </div>
                  <h3>{title}</h3>
                </div>
              ) : (
                <a href={link} target="_blank" rel="noopener noreferrer">
                  <div className="projects__item-image">
                    <img src={image} alt={title} />
                  </div>
                  <h3>{title}</h3>
                </a>
              )}
            </div>
          </SwiperSlide>
        ))}
      </Swiper>

      {/* POPUP / MODAL FOR ARTIKKELEN */}
      {isModalOpen && (
        <div className="article-modal-overlay" onClick={() => setIsModalOpen(false)}>
          <div className="article-modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="article-modal-close" onClick={() => setIsModalOpen(false)}>
              &times;
            </button>
            <article className="article-body">
              
              <h2>Du er mer enn CV-en din –<br /> om å se potensialet bak historien</h2>
              
              {/* BILDE LAGT INN I ARTIKKELEN */}
              <div className="article-image-container">
                <img src={ARTICLE_IMG} alt="Om å se potensialet" className="article-hero-image" />
              </div>

              <p>Kanskje ser du på CV-en din og tenker at du har for lite utdanning eller for mange hull til å være interessant for en arbeidsgiver.</p>
              <p>Jeg vet hvordan det kan føles å miste troen på seg selv og på hva man har å bidra med.</p>
              <p>Etter 12 år i barnehage opplevde jeg en krevende periode preget av et dårlig arbeidsmiljø, urettferdig behandling og manglende støtte og inkludering. Det påvirket meg over tid, og til slutt måtte jeg stoppe opp og finne en ny vei.</p>
              <p>Samtidig forsvant aldri interessen min for IT, teknologi og digitale løsninger. Jeg har lenge vært fascinert av hvordan man kan skape, kommunisere og løse problemer gjennom digitale verktøy. Men interessen alene synes ikke nødvendigvis på en CV.</p>
              
              <blockquote className="article-quote">
                "For kompetanse ser ikke alltid lik ut på papiret."
              </blockquote>

              <p>Et hull i CV-en eller mangel på formell utdanning betyr ikke mangel på kompetanse. Verdifull kunnskap kan også bygges gjennom erfaring, praktisk arbeid, læringsvilje og evnen til å omstille seg.</p>
              <p>Erfaring er også kompetanse. Når mennesker får muligheten til å jobbe med noe de genuint brenner for, kan det utløse motivasjon, arbeidsglede og nye krefter.</p>
              <p>Gjennom A2G har jeg fått muligheten til å bygge videre på interessen min og bruke kompetansen jeg allerede hadde. I arbeidspraksis i markedsavdelingen får jeg jobbe med innholdsproduksjon, digital kommunikasjon og web - 
                områder jeg virkelig ønsker å utvikle meg videre innen.</p>
              <p>Det har lært meg at vi ikke alltid trenger å starte helt på nytt. Noen ganger trenger vi bare en ny mulighet til å oppdage det som allerede bor i oss.</p>
              <p>Arbeidspraksis handler derfor om mer enn å fylle et hull på CV-en. Det gir mennesker muligheten til å vise hva de faktisk kan - motivasjon, omstillingsevne, arbeidserfaring, læringsvilje og et ønske om å bidra.</p>
              <p>A2G gir rom for å utvikle seg i eget tempo og vise kompetanse i praksis. Kanskje er det nettopp gjennom slike muligheter at arbeidsgivere kan få øye på spisskompetansen som ikke alltid kommer frem på papiret.</p>
              <p>For min del har det å få skape innhold og jobbe med fagområder jeg brenner for, gitt meg noe jeg hadde begynt å miste: 
                <br></br><br /><strong> Håp.</strong></p>
              <p>Jeg er fortsatt på vei. Fortsatt i utvikling. Jeg har ikke alle svarene, og veien videre er ikke ferdig tegnet.</p>
              <p>Men jeg gir ikke opp. Jeg tror på at det vil ordne seg til slutt. <br /><br />Steg for steg.</p>
            </article>
          </div>
        </div>
      )}
    </section>
  );
};

export default Projects;