import React from 'react';
import './footer.css';
import IconSocials from '../footer/IconSocials';
import LogoImg from '../../assets/logo02.png'; // Endret variabelnavn for å unngå kollisjon (sjekk også stien/path)

const Footer = () => {
  return (
    <footer>
      <section id="social">
        <IconSocials />

        {/* Klikk på logoen tar brukeren til toppen */}
        <a href="#LogoImg" className="footer__logo-link" title="Tilbake til toppen">
          <img src={LogoImg} alt="Monica Mathiassen" className="footer__logo" />
        </a>
        
      </section>
    </footer>
  );
};

export default Footer;